---@param jsonData table
---@return GachaponDojo
function GachaponDojo:Fill(jsonData)
    BaseDojo.Fill(self, jsonData)

    self.oneConsume = ConsumeDojo.New():Fill(jsonData.oneConsume)
    self.tenConsume = ConsumeDojo.New():Fill(jsonData.tenConsume)

    self.preview = {}
    for index, value in ipairs(checkTable(jsonData.preview)) do
        self.preview[index] = PreviewDojo.New():Fill(value)
    end

    self.extraPreview = {}
    for index, value in ipairs(checkTable(jsonData.extraPreview)) do
        self.extraPreview[index] = PreviewDojo.New():Fill(value)
    end

    self.rates = {}
    for rate, value in pairs(checkTable(jsonData.rates)) do
        self.rates[checkInt(rate)] = checkNumber(value) * 100  -- 直接转百分比
    end

    self.addRates = {}
    for rate, value in pairs(checkTable(jsonData.addRates)) do
        self.addRates[checkInt(rate)] = checkNumber(value) * 100  -- 直接转百分比
    end

    self.changeTimesDisplay = {}
    for rate, value in pairs(checkTable(jsonData.changeTimesDisplay)) do
        self.changeTimesDisplay[checkInt(rate)] = checkNumber(value)
    end

    self.freeData = nil
    if next(checkTable(jsonData.freeData)) ~= nil then
        self.freeData = FreeDojo.New():Fill(jsonData.freeData)
    end

    if not string.isEmpty(jsonData.givingBackPicture) then
        self.givingBackPicture = CS.ParseUtils.ParsePathNameByData(jsonData.givingBackPicture)
    end

    self.isOpenTenRed = checkInt(jsonData.isOpenTenRed)

    self.cardInformation = {}
    for _, cardId in ipairs(checkTable(jsonData.cardInformation)) do
        if checkInt(cardId) > 0 then
            table.insert(self.cardInformation, checkInt(cardId))
        end
    end

    return self
end


function GachaponDojo:IsValidActivity()
    return checkInt(self.activity.activityUuid) ~= 0
end


return GachaponDojo
